// The services' own marks, from theSVG (https://thesvg.org), the open
// brand SVG library; the trademarks belong to their owners. Each keeps
// its own colors, and each viewBox is squared with the drawing centered,
// so the icons size like the rest of the set.

// brandIcon returns a service's logo, or nil when the app has none.
func brandIcon(p store.Provider) *ui.SVG { return brandIcons[p] }

// brandTint returns the service's color, for the plate behind its logo.
func brandTint(p store.Provider) ui.Color {
	if c, ok := brandTints[p]; ok {
		return ui.Hex(c)
	}
	return ui.Color{}
}

var brandTints = map[store.Provider]string{
	store.ProviderR2:     "#F4811F",
	store.ProviderAWS:    "#7AA116",
	store.ProviderB2:     "#E21E29",
	store.ProviderWasabi: "#01CD3E",
	store.ProviderMinIO:  "#C72E49",
	store.ProviderOSS:    "#FF6A00",
	store.ProviderCOS:    "#00A3FF",
	store.ProviderSpaces: "#0080FF",
}

